// character_content.hpp - body part assets for the character customisation
// screen.
//
// This is the demo's content layer on top of the character module: it
// registers parameters, compatibility rules, rig fragments, parts, and the
// body-plan assembly profiles through the character capability, and uploads
// the part meshes to the renderer.
//
// Revision 9 mandate: "Ensure no character parts are generated by you.
// Character parts must be downloaded only." Every mesh is a VERBATIM piece
// of a downloaded, rigged CC0 model (whole artist-split mesh nodes where the
// pack provides them, otherwise the triangle subset dominated by the part's
// own rig joints; poses run through the asset's own rig). No cap/skirt/seal
// geometry, no vertex reshaping, no baked morphs, no procedural recoloring -
// see scripts/extract_parts_verbatim.py. Part origins sit on their connector
// anchors: a head's "head.root" anchor is its neck-base ring, an arm's
// "shoulder.root" its shoulder pivot, a limb's origin its joint. Junctions
// close by overlap (artist-authored part splits and socket burial), the same
// pattern documented in modules/character/docs/customization_design.md.

#ifndef ENGINE_DEMO_CHARACTER_CONTENT_HPP
#define ENGINE_DEMO_CHARACTER_CONTENT_HPP

#include "geometry.hpp"

#include <engine/character/capabilities.hpp>
#include <engine/renderer/capabilities.hpp>

#include <glm/glm.hpp>

#include <cstdint>
#include <filesystem>
#include <string>
#include <unordered_map>
#include <vector>

namespace demo
{

// Everything the screen needs to know about one registered body part asset
// on the rendering side (the module stores the anatomy side).
struct PartRenderInfo
{
    std::string                    displayName;
    std::string                    geometryId; // module-side geometry key
    std::string                    slot;       // "head", "tail", "wings"... for UI grouping
    engine::renderer::MeshMaterial material{};
};

// Body-part content for one character screen. Create before creating the
// assembly; the default character uses the profile id for the chosen body
// plan.
class CharacterContent
{
public:
    // Registers all parameters, rules, rigs, parts, and the four body-plan
    // profiles with the capability, and uploads the part meshes. assetRoot
    // is the demo assets directory (downloaded part OBJs live under
    // character_parts/). Returns false (with a message on stderr) when
    // registration failed.
    bool create(engine::character::CharacterCapability &character, const engine::renderer::RenderCapability &renderer,
        engine::renderer::RendererHandle rendererHandle, const std::string &assetRoot);

    void destroy(engine::character::CharacterCapability &character, const engine::renderer::RenderCapability &renderer,
        engine::renderer::RendererHandle rendererHandle);

    // Mesh upload keyed by the part definition's geometryId.
    engine::renderer::MeshHandle meshForGeometry(const std::string &geometryId) const;

    const PartRenderInfo *renderInfoForPart(const std::string &partId) const;

    // All part ids registered for a UI slot (head variants, quadrupeds...).
    const std::vector<std::string> &partsInSlot(const std::string &slot) const;

    std::uint32_t triangleCountForGeometry(const std::string &geometryId) const;

private:
    // CPU geometry per geometryId: the downloaded mesh as loaded.
    struct GeometryEntry
    {
        engine::renderer::MeshHandle handle = engine::renderer::invalidMesh;
        std::uint32_t                triangles = 0;
        MeshData                     rest;
        bool                         uploaded = false;
    };

    // Loads a part OBJ into the entry and uploads it.
    bool loadGeometry(const std::string &geometryId, const std::filesystem::path &path,
        const engine::renderer::RenderCapability &renderer, engine::renderer::RendererHandle rendererHandle);

    // Uploads the entry's mesh, replacing the previous GPU mesh.
    bool uploadGeometry(const std::string &geometryId, const engine::renderer::RenderCapability &renderer,
        engine::renderer::RendererHandle rendererHandle);

    std::unordered_map<std::string, GeometryEntry>            geometries_;
    std::unordered_map<std::string, PartRenderInfo>           partRenderInfo_;
    std::unordered_map<std::string, std::vector<std::string>> partsBySlot_;
};

// The four body-plan assembly profiles shipped with the demo content.
constexpr const char *humanoidProfileId  = "plan_humanoid";
constexpr const char *centaurProfileId   = "plan_centaur";
constexpr const char *nagaProfileId      = "plan_naga";
constexpr const char *quadrupedProfileId = "plan_quadruped";

// Profile id for a body-plan index (0 humanoid, 1 centaur, 2 naga, 3
// quadruped) - matches the body.plan parameter range.
inline const char *profileIdForPlan(int plan)
{
    switch (plan)
    {
    case 1:
        return centaurProfileId;
    case 2:
        return nagaProfileId;
    case 3:
        return quadrupedProfileId;
    default:
        return humanoidProfileId;
    }
}

} // namespace demo

#endif
